        ["ExecuteAsRedeemingPlayer"] = ("Als ExecAs fuer einloesenden Spieler ausfuehren", "Run as ExecAs for redeeming player"),
        ["RedeemDescription"] = ("Spieler loesen einen Code ein, indem sie ihn exakt in den Ingame-Chat schreiben, z.B. /starter. Das Tool liest denselben Chatlog wie Chat Commands und fuehrt dann den hinterlegten RCON-Command aus. Mit ExecAs wird automatisch die SteamID des einloesenden Spielers eingesetzt, also wird aus #SpawnItem Weapon_SKS 1 ein #ExecAs <SteamID> #SpawnItem Weapon_SKS 1.", "Players redeem a code by typing it exactly into in-game chat, for example /starter. The tool reads the same chat log as Chat Commands and then runs the configured RCON command. With ExecAs, the redeeming player's SteamID is inserted automatically, so #SpawnItem Weapon_SKS 1 becomes #ExecAs <SteamID> #SpawnItem Weapon_SKS 1."),
        ["RedeemAutoStart"] = ("RedeemCodes/Chat Commands automatisch starten", "Start Redeem Codes/Chat Commands automatically"),
        ["RedeemSharedSourceHint"] = ("RedeemCodes nutzen dieselbe Chatlog-Quelle wie Chat Commands. Quelle, Poll und Backfill stellst du zentral unter Settings ein.", "Redeem Codes use the same chat-log source as Chat Commands. Configure source, poll interval, and backfill centrally under Settings."),
        ["RedeemMaxUsesHint"] = ("Max. Nutzungen: 1 bedeutet einmalig fuer alle Spieler, 0 bedeutet unbegrenzt. Der Nutzungszaehler wird nach erfolgreichem Command oder erfolgreicher Antwort gespeichert. Platzhalter in Command und Antwort: {name}, {playerName}, {steamId}, {message}, {rawLine}.", "Max uses: 1 means one-time use across all players, 0 means unlimited. The usage counter is saved after a successful command or response. Placeholders in command and response: {name}, {playerName}, {steamId}, {message}, {rawLine}."),
        ["ChatCommandsDescription"] = ("Zentrale Übersicht der eingebauten Pflichtbefehle und deiner eigenen Chatregeln. Eingebaute Befehle sind immer vorhanden; aufklappen zeigt Syntax, Aliase und Voraussetzungen. Eigene Regeln bleiben bearbeitbar. Der Chatmonitor liest ggCON HTTP Logs oder SFTP; Aktionen laufen über ggCON HTTP. Mit ExecAs wird die SteamID des Chat-Spielers automatisch eingefügt.", "Central overview of required built-in commands and your custom chat rules. Built-ins are always present; expand them for syntax, aliases and prerequisites. Custom rules remain editable. The chat monitor reads ggCON HTTP logs or SFTP; actions use ggCON HTTP. ExecAs inserts the chat player's SteamID automatically."),
        ["ChatSharedSourceHint"] = ("Chat Commands und RedeemCodes nutzen dieselbe zentrale Chatlog-Quelle. ggCON HTTP/SFTP, Poll und Backfill stellst du unter Settings ein.", "Chat Commands and Redeem Codes use the same central chat-log source. Configure ggCON HTTP/SFTP, poll interval, and backfill under Settings."),
        ["ChatAutoStart"] = ("Chat Commands automatisch starten", "Start Chat Commands automatically"),
        ["WelcomeNewPlayers"] = ("Neue Spieler automatisch einmalig begruessen", "Welcome new players once automatically"),
        ["WelcomeType"] = ("Welcome Typ", "Welcome type"),
        ["WelcomeMessage"] = ("Welcome Nachricht", "Welcome message"),
        ["WelcomeHint"] = ("Wird per #MessagePlayer beim ersten erkannten Chat einer SteamID gesendet. Platzhalter: {name}, {steamId}, {message}, {rawLine}.", "Sent via #MessagePlayer when a SteamID is seen in chat for the first time. Placeholders: {name}, {steamId}, {message}, {rawLine}."),
        ["PaidVotes"] = ("Votes mit Ingamegeld kaufen", "Buy votes with in-game money"),
        ["VotePrice"] = ("Vote-Kaufpreis", "Vote price"),
        ["Confirmation"] = ("Bestaetigung", "Confirmation"),
