        ["VoteInsufficientFunds"] = ("Vote Nicht-genug-Geld-Antwort", "Vote insufficient-funds response"),
        ["Commands"] = ("Commands", "Commands"),
        ["ChatCommandsHelp"] = ("Pro Eintrag: Trigger setzen, Match-Art waehlen, optional Delay in Sekunden, Command und/oder Antwort eintragen. /wc ruft den aktuellen Challenge-Status ab. /buyevent zeigt kaufbare Buyzone-Events, /buyevent Name kauft und aktiviert privat fuer den Spieler. Platzhalter: {name}, {playerName}, {steamId}, {message}, {rawLine}, {challenges}, {challengeStatus}, {randomEvents}, {randomEventsCount}, {randomEventsLive}, {randomEventsInitiated}, {randomEventsCleanup}.", "Per entry: set the trigger, choose the match mode, optionally set a delay in seconds, then enter a command and/or response. /wc returns the current challenge status. /buyevent lists buyable Buyzone events; /buyevent Name buys and activates one privately for the player. Placeholders: {name}, {playerName}, {steamId}, {message}, {rawLine}, {challenges}, {challengeStatus}, {randomEvents}, {randomEventsCount}, {randomEventsLive}, {randomEventsInitiated}, {randomEventsCleanup}."),
