        ["ScriptStatus"] = ("Script Status", "Script status"),
        ["ScriptStatusHint"] = ("Blau = initialisiert/scharf, Gruen = gestartet/live. Gestoppte Events koennen hier manuell initiiert werden.", "Blue = initiated/armed, green = started/live. Stopped events can be initiated manually here."),
