        ["RconConsoleDescription"] = ("Befehle werden an ggCON per Source-RCON gesendet. Antworten sind in der Regel JSON.", "Commands are sent to ggCON through Source RCON. Responses are usually JSON."),
        ["DiscordBotDescription"] = ("Der Bot liest nur den angegebenen Bridge-Channel und baut daraus sichere Broadcasts. Nachrichten mit #, /, !, ., ; oder $ am Anfang werden blockiert.", "The bot reads only the configured bridge channel and turns messages into safe broadcasts. Messages starting with #, /, !, ., ;, or $ are blocked."),
        ["UseSeparateDiscordStatusBot"] = ("Eigenen Discord-Bot nur für Spielerstatus verwenden", "Use a separate Discord bot for player status only"),
        ["SeparateDiscordStatusBotHint"] = ("Dieser Bot setzt ausschließlich seine Discord-Präsenz mit der Spielerzahl und sendet keine Nachrichten. Das vollständige Serverstatus-Embed mit Wetter und Uhrzeit sendet weiterhin der Hauptbot.", "This bot only sets its Discord presence to the player count and cannot send messages. The main bot continues to send the full server status embed with weather and time."),
        ["DiscordStatusBotToken"] = ("Token des reinen Status-Bots", "Player-status bot token"),        ["ServerStatusChannelId"] = ("Serverstatus Nachricht Channel-ID", "Server status message channel ID"),
        ["ServerStatusAutoUpdate"] = ("Serverstatus als eine Nachricht automatisch aktualisieren", "Auto-update server status as one message"),
