        ["DiscordIngameEnable"] = ("Discord -> Ingame aktivieren", "Enable Discord -> in-game"),
        ["ChatlogEmbedsEnable"] = ("Chatlogs als Embed aktivieren", "Enable chat logs as embeds"),
        ["VehicleLogEmbedsEnable"] = ("Vehicle-Destruction Logs als Embed aktivieren", "Enable vehicle-destruction logs as embeds"),
        ["ChatlogsAutoStart"] = ("Chatlogs automatisch starten", "Start chat logs automatically"),
        ["GameBridgeMessageType"] = ("Message Type fuer Ingame-Broadcast", "Message type for in-game broadcast"),
        ["JoinDescription"] = ("Liest den SCUM-Loginlog per SFTP und plant nach einem Join verzoegerte RCON-Befehle. Die Regeln werden unten als einzelne Commands gepflegt; kein rohes JSON mehr noetig. Die Command-Felder haben SCUM-Autovervollstaendigung. Mit ExecAs wird die SteamID des joinenden Spielers automatisch eingefuegt.", "Reads the SCUM login log through SFTP and schedules delayed RCON commands after a player joins. Rules are edited below as individual commands; raw JSON is no longer required. Command fields provide SCUM autocomplete. ExecAs inserts the joining player's SteamID automatically."),
        ["JoinAutoStart"] = ("Join Commands automatisch starten", "Start Join Commands automatically"),
        ["JoinCommandsHelp"] = ("Pro Eintrag: aktivieren, Delay in Sekunden setzen, Command eintippen oder aus der Vorschlagsliste waehlen und optional als ExecAs fuer den joinenden Spieler ausfuehren. Eine optionale Ziel-SteamID beschraenkt die Regel auf diesen Spieler. \"Nur einmal pro Join\" meint dieselbe erkannte Login-Zeile; bei einem spaeteren Rejoin kann der Command wieder laufen. Platzhalter bleiben moeglich: {name}, {playerName}, {steamId}, {rawLine}.", "Per entry: enable it, set the delay in seconds, type a command or choose one from suggestions, and optionally run it as ExecAs for the joining player. An optional target SteamID limits the rule to that player. \"Only once per join\" means the same detected login line; after a later rejoin the command can run again. Placeholders remain available: {name}, {playerName}, {steamId}, {rawLine}."),
        ["DelaySeconds"] = ("Delay Sekunden", "Delay seconds"),
        ["TargetSteamId"] = ("Nur SteamID", "Only SteamID"),
        ["TargetSteamIdTooltip"] = ("Leer lassen = alle Spieler. Mehrere IDs mit Komma oder Leerzeichen trennen.", "Leave blank = all players. Separate multiple IDs with commas or spaces."),
        ["OnlyOncePerJoin"] = ("Nur einmal pro Join ausfuehren", "Run only once per join"),
        ["OnlyOncePerJoinTooltip"] = ("Verhindert doppelte Ausfuehrung fuer dieselbe erkannte Login-Zeile. Wenn der Spieler spaeter neu joined, kann der Command wieder geplant werden.", "Prevents duplicate execution for the same detected login line. If the player joins again later, the command can be scheduled again."),
        ["PollSeconds"] = ("Poll Sekunden", "Poll seconds"),
        ["IngameMessageColor"] = ("Ingame Nachricht Farbe", "In-game message color"),
        ["IngameMessageTemplate"] = ("Ingame Nachricht Template", "In-game message template"),
        ["WeeklyProgressTitle"] = ("Fortschritt der Herausforderungen aus scum.db", "Challenge progress from scum.db"),
        ["WeeklyDescription"] = ("Laedt die scum.db per SFTP, speichert beim Start einen Basiswert und berechnet danach nur die Differenz. Discord wird alle 30 Minuten aktualisiert, aber nur wenn Spieler online sind.", "Loads scum.db through SFTP, stores a baseline on start, and then calculates only the difference. Discord is updated every 30 minutes, but only when players are online."),
